def flat(x):
    if not isinstance(x, list):
        return [x]
    out = []
    for item in x:
        out += flat(item)
    return out

data = [1, [2, [3, 4]], [], [[5]]]
r = flat(data)
print(r, len(r), flat("ab"))

def biggest(nums):
    best = 0
    for n in nums[1:]:
        if n > best:
            best = n
    return best

